using System;using System.IO;using System.Linq;using UnityEngine;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;using UnityEditor;using UnityEditor.SceneManagement;using DigitalRuby.WeatherMaker;using LWS.TruckSports;using LWS.TruckSports.Editor;
namespace LWS.TruckBogSnorkelling.Editor {
public static class BogAuthoring {
 public const string Folder="TruckBogSnorkelling",Scene="Assets/TruckBogSnorkelling/Scenes/TruckBogSnorkelling.unity";
 public static void Create(){var m=SportsEventAuthoring.Begin<BogMatch>(Folder);m.setup.count=4;m.NormalizeSetup();m.feedback.clips=LWS.TruckHockey.Editor.HockeyAudioAuthoring.Create();m.course=m.gameObject.AddComponent<BogCourse>();var course=m.course;string path="Assets/"+Folder+"/Materials/Flooded bog terrain.asset";var data=AssetDatabase.LoadAssetAtPath<TerrainData>(path);if(data==null){data=new TerrainData();AssetDatabase.CreateAsset(data,path);}data.heightmapResolution=513;data.size=new Vector3(320,30,410);data.terrainLayers=new[]{AssetDatabase.LoadAssetAtPath<TerrainLayer>("Assets/PinwheelStudio/Vista/Personal/Samples/TerrainLayers/Grass Light/Grass_Light_VistaSample.terrainlayer"),AssetDatabase.LoadAssetAtPath<TerrainLayer>("Assets/3D Haven/Path Painter II/Editor/Demo/Terrains/DocsTerrain/TerrainLayers/stdMudRocky.terrainlayer")};var heights=new float[513,513];for(int z=0;z<513;z++)for(int x=0;x<513;x++){float wx=-160+x/512f*320,wz=-20+z/512f*410;heights[z,x]=(BogCourse.Floor(wx,wz)+5)/30;}data.SetHeights(0,0,heights);data.alphamapResolution=128;var alpha=new float[128,128,2];for(int z=0;z<128;z++)for(int x=0;x<128;x++){float wx=-160+x/127f*320,wz=-20+z/127f*410;float mud=1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(20,35,Mathf.Abs(wx-BogCourse.Center(wz))));alpha[z,x,1]=mud*.94f;alpha[z,x,0]=1-alpha[z,x,1];}data.SetAlphamaps(0,0,alpha);course.terrain=Terrain.CreateTerrainGameObject(data).GetComponent<Terrain>();course.terrain.name="Actual banked mud trenches and surfacing pockets";course.terrain.transform.position=new Vector3(-160,-5,-20);course.terrain.drawInstanced=true;var terrainMat=SportsEventAuthoring.Mat(Folder,"Bog grass and mud",Color.white);terrainMat.shader=Shader.Find("Universal Render Pipeline/Terrain/Lit");course.terrain.materialTemplate=terrainMat;
 var water=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/NWH/Vehicle Physics 2/Prefabs/Water/Water.prefab"));water.name="Installed NWH water plane with River Modeler surface";foreach(var component in water.GetComponentsInChildren<MonoBehaviour>(true))UnityEngine.Object.DestroyImmediate(component);foreach(var collider in water.GetComponentsInChildren<Collider>(true))UnityEngine.Object.DestroyImmediate(collider);water.transform.SetPositionAndRotation(new Vector3(0,1.5f,175),Quaternion.identity);water.transform.localScale=new Vector3(6,1,36.5f);course.water=water.transform;InstallWaterSurface(water);
 var metal=SportsEventAuthoring.Mat(Folder,"Snorkel black steel",new Color(.1f,.14f,.14f),.7f);metal.SetFloat("_Metallic",.65f);var cap=SportsEventAuthoring.Mat(Folder,"Intake safety orange",new Color(1,.48f,.12f),.3f);m.racers=new BogRacer[4];m.identities=new TextMesh[4];for(int i=0;i<4;i++){var t=SportsEventAuthoring.Truck(m,Folder,"Snorkel racer "+i,course.Spawn(i),i);SportsRallyAuthoring.FitTruck(t);t.maxSpeed=12;t.motorTorque=8;t.steerAngle=32;t.body.centerOfMass=new Vector3(0,-.12f,0);t.body.angularDamping=.65f;var racer=t.gameObject.AddComponent<BogRacer>();racer.match=m;racer.truck=t;Pipe(t.transform,new Vector3(.63f,.65f,.6f),new Vector3(.63f,2.15f,.6f),.085f,metal);Pipe(t.transform,new Vector3(.63f,2.15f,.6f),new Vector3(.63f,2.15f,.28f),.085f,metal);racer.intake=new GameObject("Actual air intake sampling point").transform;racer.intake.SetParent(t.transform,false);racer.intake.localPosition=new Vector3(.63f,2.15f,.28f);var cover=SportsEventAuthoring.Box("Visible orange snorkel cap",new Vector3(.63f,2.2f,.28f),new Vector3(.25f,.09f,.25f),cap,null,t.transform);racer.filter=t.engine.gameObject.AddComponent<AudioLowPassFilter>();racer.filter.cutoffFrequency=22000;racer.bubbles=Particles("Snorkel bubbles "+i,new Color(.65f,.87f,.84f,.25f),.09f,12,true);racer.sediment=Particles("Muddy tyre sediment "+i,new Color(.29f,.23f,.12f,.18f),.48f,9,true);racer.splash=Particles("Surface crossing splash "+i,new Color(.6f,.8f,.76f,.4f),.25f,0,false);for(int side=-1;side<=1;side+=2){var lamp=new GameObject("Submerged truck headlamp").AddComponent<Light>();lamp.transform.SetParent(t.transform,false);lamp.transform.localPosition=new Vector3(side*.5f,.6f,1.5f);lamp.transform.localRotation=Quaternion.Euler(7,0,0);lamp.type=LightType.Spot;lamp.spotAngle=65;lamp.innerSpotAngle=30;lamp.range=18;lamp.intensity=3;lamp.color=new Color(.9f,1,.83f);lamp.shadows=LightShadows.None;}m.racers[i]=racer;m.identities[i]=SportsEventAuthoring.Label("Bog driver identity "+i,m.setup.players[i].name,t.transform.position+Vector3.up*2.4f,.12f,m.setup.players[i].color);var nameBillboard=m.identities[i].gameObject.AddComponent<SportsPerCameraBillboard>();nameBillboard.distanceSizing=true;nameBillboard.referenceDistance=45;m.identities[i].characterSize=.075f;}
 m.views=SportsRallyAuthoring.Views(m,m.racers.Select(r=>r.truck).ToArray());m.cameras=new[]{m.views.broadcast.view};course.weather=SportsChaosAuthoring.Weather(m,Folder);m.views.weather=course.weather;course.weather.Configure(55,1,0);m.fog=course.weather.vendor.GetComponentInChildren<WeatherMakerFullScreenFogScript>(true);if(m.fog!=null&&m.fog.FogProfile!=null){string fogPath="Assets/"+Folder+"/Materials/Scoped bog weather fog.asset";var owned=AssetDatabase.LoadAssetAtPath<WeatherMakerFullScreenFogProfileScript>(fogPath);if(owned==null){owned=UnityEngine.Object.Instantiate(m.fog.FogProfile);owned.name="Bog weather fog";AssetDatabase.CreateAsset(owned,fogPath);}owned.FogDensity=0;m.fog.FogProfile=owned;m.fog.UseUnityFog=false;}m.GetComponent<LWS.TruckBaseJumping.BaseJumpRendering>().pipeline=Pipeline();m.effects=new BogCameraEffects[5];for(int i=0;i<5;i++){var camera=i==4?m.views.broadcast.view:m.views.views[i].view;m.effects[i]=camera.gameObject.AddComponent<BogCameraEffects>();m.effects[i].course=course;camera.GetUniversalAdditionalCameraData().requiresDepthTexture=true;camera.GetUniversalAdditionalCameraData().requiresColorTexture=true;}
 Dress(m,metal);ConvertScenery(m);SportsEventAuthoring.UI(m);SportsRallyAuthoring.CompactUI(m);SportsUIAuthoring.Button(m.menus.pages[0].transform,"WEATHER","weather",new Vector2(0,305),new Vector2(450,40));m.menus.optionText.GetComponent<RectTransform>().anchoredPosition=new Vector2(360,255);SportsEventAuthoring.Save(Folder);Validate();}
 static void InstallWaterSurface(GameObject water){var source=AssetDatabase.LoadAssetAtPath<Material>("Assets/RiverModeler/ShaderGraph/Default River.mat");if(source==null)throw new Exception("Installed River Modeler water material required");string path="Assets/"+Folder+"/Materials/Bog vendor water surface.mat";var material=AssetDatabase.LoadAssetAtPath<Material>(path);if(material==null){material=new Material(source);AssetDatabase.CreateAsset(material,path);}else{var copy=new Material(source);EditorUtility.CopySerialized(copy,material);UnityEngine.Object.DestroyImmediate(copy);}material.SetColor("_BaseColor",new Color(.18f,.35f,.27f,1));material.SetFloat("_Speed",.35f);material.SetFloat("_Fog_Density",1.2f);material.SetFloat("_Refraction",.008f);material.SetFloat("_Smoothness",.65f);material.SetFloat("_Metallicness",.05f);material.SetFloat("_Normal_Strength",.22f);water.name="Installed NWH surface mesh with River Modeler URP water";water.GetComponent<Renderer>().sharedMaterial=material;
 // The vendor shader uses green as its transparency-removal mask, alpha as foam, and UV2 as flow.
 var original=water.GetComponent<MeshFilter>().sharedMesh;string meshPath="Assets/"+Folder+"/Materials/Bog vendor surface mesh.asset";var mesh=AssetDatabase.LoadAssetAtPath<Mesh>(meshPath);if(mesh==null){mesh=new Mesh();AssetDatabase.CreateAsset(mesh,meshPath);}mesh.Clear();mesh.vertices=original.vertices;mesh.normals=original.normals;mesh.tangents=original.tangents;mesh.colors=new Color[original.vertexCount];var uv=new System.Collections.Generic.List<Vector2>();var flow=new System.Collections.Generic.List<Vector2>();foreach(var point in original.vertices){uv.Add(new Vector2(point.x*water.transform.localScale.x,point.z*water.transform.localScale.z));flow.Add(new Vector2(.12f,.025f));}mesh.SetUVs(0,uv);mesh.SetUVs(2,flow);mesh.subMeshCount=1;mesh.SetTriangles(original.triangles,0);mesh.RecalculateBounds();mesh.UploadMeshData(false);EditorUtility.SetDirty(mesh);EditorUtility.SetDirty(material);water.GetComponent<MeshFilter>().sharedMesh=mesh;}
 static UniversalRenderPipelineAsset Pipeline(){string folder="Assets/"+Folder+"/Rendering/";Directory.CreateDirectory(folder);AssetDatabase.Refresh();var source=AssetDatabase.LoadAssetAtPath<UniversalRenderPipelineAsset>("Assets/TruckBaseJumping/Rendering/Base pipeline.asset");var original=new SerializedObject(source).FindProperty("m_RendererDataList").GetArrayElementAtIndex(0).objectReferenceValue as ScriptableRendererData;string rendererPath=folder+"Bog renderer.asset";var renderer=AssetDatabase.LoadAssetAtPath<ScriptableRendererData>(rendererPath);if(renderer==null){renderer=UnityEngine.Object.Instantiate(original);renderer.name="Bog scoped Weather Maker and camera depth renderer";AssetDatabase.CreateAsset(renderer,rendererPath);renderer.rendererFeatures.Clear();foreach(var feature in original.rendererFeatures){if(feature==null)continue;var copy=UnityEngine.Object.Instantiate(feature);copy.name=feature.name;AssetDatabase.AddObjectToAsset(copy,renderer);renderer.rendererFeatures.Add(copy);}var underwater=ScriptableObject.CreateInstance<BogUnderwaterFeature>();underwater.name="Independent Bog underwater cameras";AssetDatabase.AddObjectToAsset(underwater,renderer);renderer.rendererFeatures.Add(underwater);EditorUtility.SetDirty(renderer);}string pipelinePath=folder+"Bog pipeline.asset";var pipeline=AssetDatabase.LoadAssetAtPath<UniversalRenderPipelineAsset>(pipelinePath);if(pipeline==null){pipeline=UnityEngine.Object.Instantiate(source);pipeline.name="Bog scene-owned pipeline";AssetDatabase.CreateAsset(pipeline,pipelinePath);}var so=new SerializedObject(pipeline);var list=so.FindProperty("m_RendererDataList");list.arraySize=1;list.GetArrayElementAtIndex(0).objectReferenceValue=renderer;so.FindProperty("m_DefaultRendererIndex").intValue=0;so.ApplyModifiedPropertiesWithoutUndo();pipeline.renderScale=1;pipeline.supportsCameraDepthTexture=true;pipeline.supportsCameraOpaqueTexture=true;return pipeline;}
 static void Pipe(Transform parent,Vector3 a,Vector3 b,float radius,Material mat){var g=GameObject.CreatePrimitive(PrimitiveType.Cylinder);g.name="Modelled snorkel tube";UnityEngine.Object.DestroyImmediate(g.GetComponent<Collider>());g.transform.SetParent(parent,false);g.transform.localPosition=(a+b)*.5f;g.transform.localRotation=Quaternion.FromToRotation(Vector3.up,(b-a).normalized);g.transform.localScale=new Vector3(radius*2,(b-a).magnitude*.5f,radius*2);g.GetComponent<Renderer>().sharedMaterial=mat;}
 static ParticleSystem Particles(string name,Color color,float size,float rate,bool loop){var p=new GameObject(name).AddComponent<ParticleSystem>();p.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);var main=p.main;main.loop=loop;main.playOnAwake=false;main.simulationSpace=ParticleSystemSimulationSpace.World;main.startLifetime=loop?1.3f:.7f;main.startSpeed=loop?.7f:2;main.startSize=size;main.startColor=color;main.maxParticles=96;main.gravityModifier=-.07f;var emission=p.emission;emission.rateOverTime=rate;if(!loop)emission.SetBursts(new[]{new ParticleSystem.Burst(0,24)});var shape=p.shape;shape.shapeType=ParticleSystemShapeType.Cone;shape.radius=.15f;shape.angle=25;var renderer=p.GetComponent<ParticleSystemRenderer>();var material=SportsChaosAuthoring.Flare(Folder);material.SetFloat("_Blend",0);material.SetInt("_DstBlend",(int)BlendMode.OneMinusSrcAlpha);renderer.sharedMaterial=material;renderer.shadowCastingMode=ShadowCastingMode.Off;return p;}
 static void Dress(BogMatch m,Material metal){var root=new GameObject("Bog banks and authentic installed course props").transform;var board=SportsEventAuthoring.Contact(Folder,"Low underwater beam contact",.4f,.05f);for(int i=0;i<m.course.logs.Length;i++){float z=m.course.logs[i],x=BogCourse.Center(z);var holder=new GameObject("Low timber dive barrier "+i).transform;holder.SetParent(root);holder.position=new Vector3(x+(i==2?-6:0),i==2?1.1f:.9f,z);LWS.TruckKeepaway.Editor.KeepawayPresentationAuthoring.Fit(holder,"Assets/ConstructionPropsBundle/URP/Prefabs/SM_Planks01 Variant.prefab",new Vector3(i==2?23:50,.6f,2),0,true);var shape=holder.gameObject.AddComponent<BoxCollider>();shape.center=new Vector3(0,.3f,0);shape.size=new Vector3(i==2?23:50,.6f,2);shape.sharedMaterial=board;var caption=SportsEventAuthoring.Label("Physical dive marker "+i,"DIVE UNDER",new Vector3(x,3.7f,z),.19f,new Color(1,.77f,.2f));caption.gameObject.AddComponent<SportsPerCameraBillboard>();}
 for(int i=0;i<130;i++){float z=-5+i*2.9f,side=i%2==0?-1:1;var point=m.course.Surface(new Vector3(BogCourse.Center(z)+side*(27+i%4*1.2f),0,z));SportsRallyAuthoring.Prop(root,"Assets/JC_LP_MegaCity/Prefabs/Nature/SM_Nature_Grass_01.prefab",point,new Vector3(2.8f,2.3f,2.8f));if(i%4==0)LWS.TruckBaseJumping.Editor.BaseSkyAuthoring.Scenery(root,m.course.Surface(new Vector3(BogCourse.Center(z)+side*38,0,z)),7,i%8==0,Folder);}for(int i=0;i<m.course.checkpoints.Length;i++){float z=m.course.checkpoints[i];for(int side=-1;side<=1;side+=2){var point=m.course.Surface(new Vector3(BogCourse.Center(z)+side*24,0,z));SportsRallyAuthoring.Prop(root,"Assets/RoadPropsPack/URP/Prefabs/TrafficCone_URP.prefab",point,new Vector3(1.7f,2.4f,1.7f));var t=SportsEventAuthoring.Label("Bog checkpoint "+i,"AIR POCKET · FLAG "+(i+1),point+Vector3.up*3,.16f,new Color(.75f,1,.7f));t.gameObject.AddComponent<SportsPerCameraBillboard>();}}var branch=SportsEventAuthoring.Label("Longer shallow branch","SHALLOW ROUTE →",new Vector3(13,3.5f,142),.2f,Color.white);branch.gameObject.AddComponent<SportsPerCameraBillboard>();}
 static void ConvertScenery(BogMatch m){foreach(var renderer in UnityEngine.Object.FindObjectsByType<MeshRenderer>(FindObjectsInactive.Include)){if(!renderer.transform.IsChildOf(GameObject.Find("Bog banks and authentic installed course props").transform))continue;var materials=renderer.sharedMaterials;for(int i=0;i<materials.Length;i++){var source=materials[i];if(source==null||source.shader.name.Contains("Universal Render Pipeline"))continue;string name="Bog URP scenery "+source.name;var owned=SportsEventAuthoring.Mat(Folder,name,source.HasProperty("_Color")?source.color:new Color(.38f,.43f,.3f),.15f);if(source.mainTexture!=null)owned.mainTexture=source.mainTexture;materials[i]=owned;}renderer.sharedMaterials=materials;}}
 public static void Validate(){EditorSceneManager.OpenScene(Scene);var m=UnityEngine.Object.FindAnyObjectByType<BogMatch>();if(m==null||m.racers.Length!=4||m.effects.Length!=5||m.course.water==null||m.GetComponent<LWS.TruckBaseJumping.BaseJumpRendering>().pipeline==null)throw new Exception("Bog scene references missing");if(UnityEngine.Object.FindObjectsByType<AudioListener>(FindObjectsInactive.Include).Length!=1)throw new Exception("Bog one listener");if(m.racers.Any(r=>r.intake==null||r.bubbles==null||r.filter==null))throw new Exception("Bog intake or feedback missing");if(m.course.terrain.terrainData.GetAlphamaps(64,25,1,1)[0,0,1]<.9f)throw new Exception("Bog mud must be painted into trench");if(!m.course.water.GetComponent<Renderer>().sharedMaterial.shader.name.Contains("River"))throw new Exception("Installed River Modeler water surface required");Debug.Log("BOG_SAVED_VALIDATED actual water intake and independent underwater cameras");}
}
